import{_ as t,c as i,o as r,ag as l}from"./chunks/framework.Ds6Eueu6.js";const g=JSON.parse('{"title":"Javascript基础","description":"","frontmatter":{},"headers":[],"relativePath":"basic/htmlcssjs/js/index.md","filePath":"basic/htmlcssjs/js/index.md","lastUpdated":1745417180000}'),o={name:"basic/htmlcssjs/js/index.md"};function s(e,a,n,c,d,h){return r(),i("div",null,a[0]||(a[0]=[l('<h1 id="javascript基础" tabindex="-1">Javascript基础 <a class="header-anchor" href="#javascript基础" aria-label="Permalink to &quot;Javascript基础&quot;">​</a></h1><p>JavaScript 是一种强大的编程语言，广泛用于网页开发和服务器端开发。以下是 JavaScript 的详细概括及其构成部分：</p><h3 id="_1-核心语言-ecmascript" tabindex="-1">1. <strong>核心语言（ECMAScript）</strong> <a class="header-anchor" href="#_1-核心语言-ecmascript" aria-label="Permalink to &quot;1. **核心语言（ECMAScript）**&quot;">​</a></h3><ul><li><strong>标准</strong>：JavaScript 的核心由 ECMAScript 标准定义。</li><li><strong>功能</strong>： <ul><li>数据类型（如字符串、数字、布尔值等）。</li><li>控制结构（如 <code>if</code>、<code>for</code>、<code>while</code> 等）。</li><li>函数和对象。</li><li>数组、日期等内置对象。</li></ul></li></ul><h3 id="_2-文档对象模型-dom" tabindex="-1">2. <strong>文档对象模型（DOM）</strong> <a class="header-anchor" href="#_2-文档对象模型-dom" aria-label="Permalink to &quot;2. **文档对象模型（DOM）**&quot;">​</a></h3><ul><li><strong>定义</strong>：DOM 是浏览器提供的接口，允许 JavaScript 操作网页内容。</li><li><strong>功能</strong>： <ul><li>动态修改 HTML 元素的属性、样式和内容。</li><li>响应用户事件（如点击、键盘输入等）。</li><li>操作页面结构（如添加、删除节点）。</li></ul></li></ul><h3 id="_3-浏览器对象模型-bom" tabindex="-1">3. <strong>浏览器对象模型（BOM）</strong> <a class="header-anchor" href="#_3-浏览器对象模型-bom" aria-label="Permalink to &quot;3. **浏览器对象模型（BOM）**&quot;">​</a></h3><ul><li><strong>定义</strong>：BOM 提供了与浏览器交互的接口。</li><li><strong>功能</strong>： <ul><li>控制窗口和框架（如打开、关闭窗口）。</li><li>处理浏览器历史记录。</li><li>获取屏幕信息和位置信息。</li></ul></li></ul><h3 id="_4-扩展库和框架" tabindex="-1">4. <strong>扩展库和框架</strong> <a class="header-anchor" href="#_4-扩展库和框架" aria-label="Permalink to &quot;4. **扩展库和框架**&quot;">​</a></h3><ul><li><strong>库</strong>：如 jQuery、Lodash 等，提供便捷的功能封装。</li><li><strong>框架</strong>：如 React、Vue、Angular 等，帮助构建复杂的前端应用。</li></ul><h3 id="_5-运行环境" tabindex="-1">5. <strong>运行环境</strong> <a class="header-anchor" href="#_5-运行环境" aria-label="Permalink to &quot;5. **运行环境**&quot;">​</a></h3><ul><li><strong>浏览器端</strong>：在浏览器中运行，提供 DOM 和 BOM 支持。</li><li><strong>服务器端</strong>：通过 Node.js 运行，支持后端开发。</li></ul>',12)]))}const _=t(o,[["render",s]]);export{g as __pageData,_ as default};
